# Tm5TempoTimerStart  (CPU 0x484477c2)
#   TM5 bring-up (the sequence the MAME driver models): mode
#   0x34001082 low3 := 1, reload 0x34001092 := 0x28B0 (= 120 BPM),
#   bset/bclr 0x40 (load pulse), bset 0x80 (count enable)
Tm5TempoTimerStart:
    movbu   (TM5MD), d0
    and     0xfffffff8, d0
    or      0x01, d0
